/* The side panel on its own — 330×852, no conversation behind it. */
.side-panel {
  width: 330px;
  height: 852px;
  padding-top: 52px;
  border-radius: 40px;
  background: var(--bg-canvas);
  box-shadow: 0 4px 20px 0 rgba(113, 117, 142, 0.25);
}

.side-panel__content {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 24px 8px;
}

/* Five nav rows at 46 high, so the list below starts 64px lower than it did. */
.recents { display: flex; flex-direction: column; gap: 4px; }

.recents__item {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 40px;
  padding: 8px;
  border-radius: 16px;
}

.recents__title {
  font: 400 15px/22px var(--font-ui);
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

