// The panel is a fixed 330pt surface, not a sheet.
struct SidePanel: View {
  var body: some View {
    VStack(alignment: .leading, spacing: 24) {
      HStack(spacing: 8) {
        Image("pc-chat-mark").frame(width: 24, height: 24)
        Text("PC Chat").font(.custom("Poppins-SemiBold", size: 20))
      }
      .padding(.horizontal, 24)
      .padding(.top, 24)

      VStack(spacing: 0) {
        NavItem(icon: "square.and.pencil", label: "New chat")
        NavItem(icon: "bubble.left", label: "Chat history")
        NavItem(icon: "book", label: "Memory")
        NavItem(icon: "gear", label: "Settings")
      }

      VStack(alignment: .leading, spacing: 8) {
        Text("Recents").font(.system(size: 15, weight: .semibold))
          .padding(.horizontal, 8)
        VStack(spacing: 4) { ForEach(recents) { RecentRow(row: $0) } }
      }
    }
    .padding(8)
    .frame(width: 330, height: 852, alignment: .top)
    .background(Color.white)
    .clipShape(RoundedRectangle(cornerRadius: 40))
  }
}
